CREATE TABLE "Level" ("id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL, "roomId" TEXT NOT NULL, "order" INTEGER NOT NULL, "title" TEXT NOT NULL, "difficulty" TEXT NOT NULL, "configJson" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Level_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Level_slug_key" ON "Level"("slug");
CREATE TABLE "Attempt" ("id" TEXT NOT NULL PRIMARY KEY, "sessionId" TEXT NOT NULL, "levelId" TEXT NOT NULL, "userInputRedacted" TEXT NOT NULL, "assistantOutputRedacted" TEXT NOT NULL, "inputTokenEstimate" INTEGER NOT NULL, "outputTokenEstimate" INTEGER NOT NULL, "guardBlocked" BOOLEAN NOT NULL DEFAULT false, "guardTagsJson" TEXT NOT NULL, "scoreDelta" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Attempt_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "PlayerSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Attempt_levelId_fkey" FOREIGN KEY ("levelId") REFERENCES "Level" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Progress" ("id" TEXT NOT NULL PRIMARY KEY, "sessionId" TEXT NOT NULL, "levelId" TEXT NOT NULL, "status" TEXT NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "hintsUsed" INTEGER NOT NULL DEFAULT 0, "score" INTEGER NOT NULL DEFAULT 1000, "completedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Progress_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "PlayerSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Progress_levelId_fkey" FOREIGN KEY ("levelId") REFERENCES "Level" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
