CREATE TABLE "GuardEvent" ("id" TEXT NOT NULL PRIMARY KEY, "sessionId" TEXT NOT NULL, "levelId" TEXT NOT NULL, "attemptId" TEXT, "guardName" TEXT NOT NULL, "severity" TEXT NOT NULL, "publicMessage" TEXT, "internalReasonRedacted" TEXT, "tagsJson" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "GuardEvent_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "PlayerSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "GuardEvent_levelId_fkey" FOREIGN KEY ("levelId") REFERENCES "Level" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "GuardEvent_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "Attempt" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "HintUsage" ("id" TEXT NOT NULL PRIMARY KEY, "sessionId" TEXT NOT NULL, "levelId" TEXT NOT NULL, "hintIndex" INTEGER NOT NULL, "penalty" INTEGER NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "HintUsage_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "PlayerSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "HintUsage_levelId_fkey" FOREIGN KEY ("levelId") REFERENCES "Level" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
