CREATE TABLE "LeaderboardEntry" ("id" TEXT NOT NULL PRIMARY KEY, "sessionId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "totalScore" INTEGER NOT NULL DEFAULT 0, "completedLevels" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "LeaderboardEntry_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "PlayerSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
